#include "dod.h"
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static const char *history_name;
#define HC(x) do{if(!(x)){fprintf(stderr,"DOD_CHECK:%s:history:%d:%s\n",history_name,__LINE__,#x);exit(1);}}while(0)
static unsigned long sparse_edges,tree_edges;
static void columns(void){unsigned cases=0;for(size_t n=0;n<=4;++n){unsigned combinations=1;for(size_t i=0;i<n;++i)combinations*=9;for(unsigned code=0;code<combinations;++code)for(unsigned tick=0;tick<3;++tick){int ticks=tick==2?10:(int)tick;unsigned script=code;DColumns c={{91,92,93,94},{81,82,83,84},{11,12,13,14},n};int32_t expected[4];for(unsigned i=0;i<4;++i)expected[i]=c.x[i];for(size_t i=0;i<n;++i){c.x[i]=(int)(script%3)-1;script/=3;c.velocity[i]=(int)(script%3)-1;script/=3;expected[i]=(int32_t)((int64_t)c.x[i]+(int64_t)c.velocity[i]*ticks);}DColumns before=c;HC(d_columns_step(&c,ticks)==D_OK);for(unsigned i=0;i<4;++i)HC(c.x[i]==expected[i]&&c.velocity[i]==before.velocity[i]&&c.cold[i]==before.cold[i]);++cases;}}
 for(unsigned bad=0;bad<4;++bad)for(unsigned sign=0;sign<2;++sign){DColumns c={{1,2,3,4},{1,1,1,1},{9,8,7,6},4};c.x[bad]=sign?INT32_MIN:INT32_MAX;c.velocity[bad]=sign?-1:1;DColumns before=c;HC(d_columns_step(&c,1)==D_RANGE);for(unsigned i=0;i<4;++i)HC(c.x[i]==before.x[i]&&c.velocity[i]==before.velocity[i]&&c.cold[i]==before.cold[i]);}
 HC(cases==22143);printf("history columns: %u signed-product cases and8 late-rejection cases\n",cases);}
typedef struct {unsigned attempts,fail_at,live,releases;} HA;
static unsigned char *alloc(void *ctx,size_t n){HA *a=ctx;++a->attempts;if(a->fail_at==a->attempts)return NULL;unsigned char *p=malloc(n);HC(p);++a->live;return p;}
static void dealloc(void *ctx,unsigned char *p){HA *a=ctx;HC(a->live&&p);--a->live;++a->releases;free(p);}
static void small(void){unsigned cases=0;unsigned char initial[128],extra[129];for(unsigned i=0;i<129;++i){extra[i]=(unsigned char)(255-i);if(i<128)initial[i]=(unsigned char)i;}
 for(size_t n=0;n<=128;++n)for(size_t add=0;add<=129;++add)for(unsigned fail=0;fail<2;++fail){HA a={0};DSmall s;d_small_init(&s,(DAllocator){&a,alloc,dealloc});HC(d_small_append(&s,initial,n)==D_OK);size_t capacity=s.capacity;unsigned char *old=s.heap;a.fail_at=fail?a.attempts+1:0;int result=d_small_append(&s,extra,add);int wanted=add>128-n?D_FULL:fail&&n+add>capacity?D_FAILED:D_OK;HC(result==wanted);size_t length=wanted==D_OK?n+add:n;HC(s.length==length);if(wanted!=D_OK)HC(s.heap==old&&s.capacity==capacity);const unsigned char *bytes=d_small_data(&s);for(size_t i=0;i<length;++i)HC(bytes[i]==(i<n?initial[i]:extra[i-n]));HC(d_small_move(&s,&s)==D_INVALID);d_small_reset(&s);d_small_reset(&s);HC(a.live==0);++cases;}
 for(size_t n=0;n<=16;++n){HA a={0};DSmall s,d;d_small_init(&s,(DAllocator){&a,alloc,dealloc});d_small_init(&d,(DAllocator){&a,alloc,dealloc});HC(d_small_append(&s,initial,128)==D_OK&&d_small_append(&d,extra,1)==D_OK);HC(d_small_move(&d,&s)==D_INVALID&&s.length==128&&d.length==1);HC(d_small_compact(&s)==D_FULL);HC(d_small_truncate(&s,n)==D_OK&&d_small_compact(&s)==D_OK&&!s.heap&&s.capacity==16&&!a.live);for(size_t i=0;i<n;++i)HC(d_small_data(&s)[i]==initial[i]);d_small_reset(&d);HC(d_small_move(&d,&s)==D_OK&&d.length==n&&!s.length);d_small_reset(&s);d_small_reset(&d);HC(a.live==0&&a.releases==1);}
 HC(cases==33540);printf("history small: %u length/failure cases and17 compact/move boundaries\n",cases);}
static uint32_t scalar8(uint32_t a,uint32_t b){uint32_t out=0;for(unsigned lane=0;lane<4;++lane){unsigned n=((a>>(lane*8))&255)+((b>>(lane*8))&255);out|=(uint32_t)(n>255?255:n)<<(lane*8);}return out;}
static void swar(void){for(unsigned a=0;a<256;++a)for(unsigned b=0;b<256;++b)for(unsigned lane=0;lane<4;++lane)for(unsigned pattern=0;pattern<2;++pattern){uint32_t mask=UINT32_C(255)<<(lane*8),x=(pattern?UINT32_C(0xff00ff00):UINT32_C(0x00ff00ff))&~mask,y=UINT32_C(0x01010101)&~mask;x|=(uint32_t)a<<(lane*8);y|=(uint32_t)b<<(lane*8);HC(d_swar_add(x,y)==scalar8(x,y));}uint32_t random=1;for(unsigned i=0;i<100000;++i){random=random*1664525u+1013904223u;uint32_t a=random;random=random*1664525u+1013904223u;uint32_t b=random;HC(d_swar_add(a,b)==scalar8(a,b));}puts("history swar: 524288 neighboring-boundary cases and100000 seeded mixed words");}
typedef struct {unsigned slot,generation,issued;} Token;
typedef struct {unsigned generation[4],live[4];int value[4];Token latest[4],issued[7];unsigned count;} SparseModel;
static int sparse_step(DSparse *s,SparseModel *m,unsigned operation){unsigned id=operation%4;if(operation<4){unsigned slot=0;while(slot<4&&(m->live[slot]||m->generation[slot]>3))++slot;DHandle h={NULL,99,98};int status=d_sparse_add(s,(int)id,&h);HC(status==(slot==4?D_FULL:D_OK));if(slot==4)HC(!h.owner&&h.slot==99&&h.generation==98);else{HC(h.owner==s&&h.slot==slot&&h.generation==m->generation[slot]);m->live[slot]=1;m->value[slot]=(int)id;m->latest[id]=(Token){slot,m->generation[slot],1};m->issued[m->count++]=m->latest[id];}return status;}Token t=m->latest[id];DHandle h={t.issued?s:NULL,t.slot,t.generation};int valid=t.issued&&m->live[t.slot]&&m->generation[t.slot]==t.generation;int status=d_sparse_remove(s,h);HC(status==(valid?D_OK:D_STALE));if(valid){m->live[t.slot]=0;++m->generation[t.slot];}return status;}
static void sparse_check(const DSparse *s,const SparseModel *m){unsigned count=0,seen=0;for(unsigned slot=0;slot<4;++slot){HC(s->slots[slot].generation==m->generation[slot]&&s->slots[slot].live==m->live[slot]);if(m->live[slot]){++count;HC(s->slots[slot].value==m->value[slot]&&s->rank[slot]<s->count&&s->dense[s->rank[slot]]==slot);}}HC(s->count==count);for(unsigned row=0;row<s->count;++row){unsigned slot=s->dense[row];HC(slot<4&&!(seen&(1u<<slot))&&m->live[slot]&&s->rank[slot]==row);seen|=1u<<slot;}for(unsigned i=0;i<m->count;++i){Token t=m->issued[i];int value=91;int valid=m->live[t.slot]&&m->generation[t.slot]==t.generation;HC(d_sparse_get(s,(DHandle){s,t.slot,t.generation},&value)==(valid?D_OK:D_STALE));HC(value==(valid?m->value[t.slot]:91));}}
static void sparse_walk(const DSparse *s,const SparseModel *m,unsigned depth){sparse_check(s,m);if(depth==7)return;for(unsigned op=0;op<8;++op){DSparse next=*s;SparseModel model=*m;(void)sparse_step(&next,&model,op);++sparse_edges;sparse_walk(&next,&model,depth+1);}}
static void sparse(void){DSparse s,foreign;d_sparse_init(&s);d_sparse_init(&foreign);SparseModel m={{1,1,1,1},{0},{0},{{0}},{{0}},0};sparse_walk(&s,&m,0);HC(sparse_edges==2396744ul);DHandle h;HC(d_sparse_add(&s,5,&h)==D_OK);int out=91;HC(d_sparse_get(&foreign,h,&out)==D_STALE&&out==91);HC(d_sparse_remove(&foreign,h)==D_STALE);printf("history sparse: %lu operation prefixes; all issued tokens and both bijection directions checked\n",sparse_edges);}
static void tree_check(const DTree *t,const unsigned roots[6],int model[6][8],unsigned depth){HC(t->used==4*depth);unsigned incoming[65]={0},seen[65]={0};for(unsigned version=0;version<=depth;++version){if(roots[version])++incoming[roots[version]];for(unsigned i=0;i<8;++i){int value=91;HC(d_tree_get(t,roots[version],i,&value)==D_OK&&value==model[version][i]);}unsigned todo[65],n=0;if(roots[version])todo[n++]=roots[version];while(n){unsigned node=todo[--n];if(seen[node])continue;seen[node]=1;DTreeNode p=t->nodes[node];HC(p.left<node&&p.right<node);if(p.left){++incoming[p.left];todo[n++]=p.left;}if(p.right){++incoming[p.right];todo[n++]=p.right;}}}for(unsigned i=1;i<=t->used;++i)HC(seen[i]&&incoming[i]);}
static void tree_walk(const DTree *t,const unsigned roots[6],int model[6][8],unsigned depth){tree_check(t,roots,model,depth);if(depth==5)return;const unsigned indices[3]={0,3,7};const int values[3]={0,1,-1};for(unsigned op=0;op<9;++op){unsigned index=indices[op/3];int value=values[op%3];for(unsigned cut=1;cut<=4;++cut){DTree fail=*t;fail.fail_after=cut;unsigned out=999;HC(d_tree_update(&fail,roots[depth],index,value,&out)==D_FAILED&&out==999&&fail.used==t->used);for(unsigned i=1;i<=t->used;++i)HC(fail.nodes[i].left==t->nodes[i].left&&fail.nodes[i].right==t->nodes[i].right&&fail.nodes[i].value==t->nodes[i].value);tree_check(&fail,roots,model,depth);}DTree next=*t;unsigned new_roots[6];int new_model[6][8];memcpy(new_roots,roots,sizeof new_roots);memcpy(new_model,model,sizeof new_model);memcpy(new_model[depth+1],model[depth],sizeof new_model[0]);new_model[depth+1][index]=value;HC(d_tree_update(&next,roots[depth],index,value,&new_roots[depth+1])==D_OK);++tree_edges;tree_walk(&next,new_roots,new_model,depth+1);}}
static void persistent(void){DTree t;d_tree_init(&t);unsigned roots[6]={0};int model[6][8]={{0}};tree_walk(&t,roots,model,0);HC(tree_edges==66429ul);printf("history persistent: %lu successful prefixes,265716 allocation cuts, every retained root and8 cells\n",tree_edges);}
static void oracle(void){const unsigned indices[3]={0,3,7};const int values[3]={0,1,-1};for(unsigned code=0;code<729;++code){unsigned script=code,roots[4]={0};DTree t;d_tree_init(&t);for(unsigned step=0;step<3;++step){unsigned op=script%9;script/=9;HC(d_tree_update(&t,roots[step],indices[op/3],values[op%3],&roots[step+1])==D_OK);for(unsigned version=0;version<=step+1;++version){printf("T %u %u %u",code,step,version);for(unsigned i=0;i<8;++i){int v;HC(d_tree_get(&t,roots[version],i,&v)==D_OK);printf(" %d",v);}puts("");}}}for(unsigned code=0;code<512;++code){unsigned script=code;DSparse s;d_sparse_init(&s);SparseModel m={{1,1,1,1},{0},{0},{{0}},{{0}},0};for(unsigned step=0;step<3;++step){unsigned op=script%8;script/=8;int status=sparse_step(&s,&m,op);printf("S %u %u %d %u",code,step,status,s.count);for(unsigned i=0;i<4;++i)printf(" %u %u %d",s.slots[i].generation,s.slots[i].live,s.slots[i].live?s.slots[i].value:0);puts("");}}}
void d_histories(const char *name){history_name=name;if(!strcmp(name,"columns"))columns();else if(!strcmp(name,"small"))small();else if(!strcmp(name,"swar"))swar();else if(!strcmp(name,"sparse"))sparse();else if(!strcmp(name,"persistent"))persistent();else if(!strcmp(name,"oracle"))oracle();}
